import json

def load_demo_pairs(filepath):
    with open(filepath, 'r') as f:
        return json.load(f)

def transform(grid):
    """
    For this task: 
    - Find connected shapes of non-background (non-9) cells
    - For shapes that have "open ends" forming a loop or closed shape with a hole
    - Fill the hole/enclosed area with 1s
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find connected components of non-9 cells
    visited = [[False]*cols for _ in range(rows)]
    shapes = []

    def find_component(start_r, start_c):
        """Find all cells in a connected component (4-connectivity)"""
        component = []
        stack = [(start_r, start_c)]
        local_visited = [[False]*cols for _ in range(rows)]

        while stack:
            r, c = stack.pop()
            if local_visited[r][c] or visited[r][c]:
                continue
            local_visited[r][c] = visited[r][c] = True
            component.append((r, c))

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] != 9:
                        stack.append((nr, nc))
        return component

    # Find all components
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 9 and not visited[r][c]:
                comp = find_component(r, c)
                shapes.append(comp)

    # For each shape, check if it encloses any cells (has a hole)
    # A cell is enclosed if all paths to the edge go through the shape
    output = [row[:] for row in grid]

    for shape in shapes:
        if len(shape) < 4:
            continue  # Too small to have a hole

        # Try to find "enclosed" cells - cells that are 9 but surrounded
        # by the shape in all four directions (looking from each enclosure candidate)
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 9:
                    # Check if this cell is enclosed by a shape
                    # A cell is enclosed if there's NO path to the edge without going through shape
                    # Simple approach: flood fill from this cell, if we can't reach edge, it's enclosed
                    reachable = False
                    stack = [(r, c)]
                    locally_visited = set()

                    while stack:
                        cr, cc = stack.pop()
                        if (cr, cc) in locally_visited:
                            continue
                        locally_visited.add((cr, cc))

                        # Check if we've reached the edge
                        if cr == 0 or cr == rows-1 or cc == 0 or cc == cols-1:
                            reachable = True
                            break

                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if (nr, nc) not in locally_visited:
                                    if grid[nr][nc] == 9:
                                        stack.append((nr, nc))
                                    elif (nr, nc) in shape:
                                        reachable = True
                                        break
                    if reachable:
                        break

                    if not reachable:
                        # This cell is enclosed - change to 1
                        output[r][c] = 1

    return output

