# Test hypothesis: Replace all 2s with 1s that are part of a rightward block
def transform(row):
    result = row[:]
    # Find rightmost 3 in the row
    rightmost_3 = -1
    for c in range(len(row)):
        if row[c] == 3:
            rightmost_3 = c

    # Convert all 2s that are to the right of rightmost 3
    for c in range(len(result)):
        if result[c] == 2 and c > rightmost_3:
            result[c] = 1
    return result

